--
-- Name: fato_arrecadacao_mensal; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.fato_arrecadacao_mensal AS
 SELECT r.emp_proprietaria_id,
    make_date((r.ordem / 100), (r.ordem % 100), 1) AS mes,
    COALESCE(r.tipo, 'Associativa'::text) AS tipo,
    COALESCE(l.fonte_pg_id, r.emp_contratante_id) AS fonte_id,
    COALESCE(l.fonte_pg_id, r.emp_contratante_id, '00000000-0000-0000-0000-000000000000'::uuid) AS fonte_chave,
    (sum(COALESCE(l.valor, (0)::numeric)))::numeric(14,2) AS valor,
    (count(*))::integer AS lancamentos,
    (count(DISTINCT COALESCE((l.filiado_id)::text, l.cpf)))::integer AS pagantes
   FROM (public.filiacao_recebe_remessa r
     JOIN public.filiacao_recebe l ON ((l.remessa_id = r.id)))
  WHERE ((r.ordem IS NOT NULL) AND ((r.ordem >= 200001) AND (r.ordem <= 210012)) AND (((r.ordem % 100) >= 1) AND ((r.ordem % 100) <= 12)))
  GROUP BY r.emp_proprietaria_id, (make_date((r.ordem / 100), (r.ordem % 100), 1)), COALESCE(r.tipo, 'Associativa'::text), COALESCE(l.fonte_pg_id, r.emp_contratante_id), COALESCE(l.fonte_pg_id, r.emp_contratante_id, '00000000-0000-0000-0000-000000000000'::uuid)
  WITH NO DATA;


--
-- Name: analitica_arrecadacao(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analitica_arrecadacao(p_emp uuid, p_meses integer DEFAULT 12) RETURNS SETOF public.fato_arrecadacao_mensal
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from public.fato_arrecadacao_mensal
  where emp_proprietaria_id = p_emp and mes >= date_trunc('month', now()) - make_interval(months => greatest(p_meses, 1) - 1)
  order by mes, tipo
$$;


--
-- Name: analitica_atualizar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analitica_atualizar() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_inicio timestamptz;
  v_fato text;
  v_saida jsonb := '{}'::jsonb;
begin
  foreach v_fato in array array['fato_filiacao_mensal','fato_arrecadacao_mensal','fato_despesa_mensal','fato_frota_mensal'] loop
    v_inicio := clock_timestamp();
    execute format('refresh materialized view concurrently public.%I', v_fato);
    insert into public.analitica_atualizacoes (fato, atualizado_em, duracao_ms)
    values (v_fato, now(), (extract(epoch from clock_timestamp() - v_inicio) * 1000)::int)
    on conflict (fato) do update set atualizado_em = excluded.atualizado_em, duracao_ms = excluded.duracao_ms;
    v_saida := v_saida || jsonb_build_object(v_fato, (extract(epoch from clock_timestamp() - v_inicio) * 1000)::int);
  end loop;
  return v_saida;
end;
$$;


