--
-- Name: anonimizar_filiacao(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anonimizar_filiacao(p_filiacao_id uuid, p_emp uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cpf      text;
  v_digitos  text;
  v_ids      uuid[];
  n_fil      integer := 0;
  n_tel      integer := 0;
  n_end      integer := 0;
  n_banc     integer := 0;
  n_cont     integer := 0;
  n_ident    integer := 0;
  n_saude    integer := 0;
  n_aceites  integer := 0;
begin
  select cpf into v_cpf
    from filiacoes
   where id = p_filiacao_id and emp_proprietaria_id = p_emp;
  if not found then
    raise exception 'Filiação % não encontrada no tenant', p_filiacao_id;
  end if;
  v_digitos := nullif(regexp_replace(coalesce(v_cpf, ''), '\D', '', 'g'), '');

  -- Todos os registros da MESMA pessoa (mesmo CPF, qualquer grafia) no tenant.
  if v_digitos is null then
    v_ids := array[p_filiacao_id];
  else
    select coalesce(array_agg(id), array[p_filiacao_id]) into v_ids
      from filiacoes
     where emp_proprietaria_id = p_emp
       and regexp_replace(coalesce(cpf, ''), '\D', '', 'g') = v_digitos;
  end if;

  update filiacoes set
    nome_completo = 'Titular anonimizado',
    nome_social = null,
    nome_completo_norm = null,
    foto = null,
    sexo = null,
    nascimento_data = null,
    nascimento_dia = null,
    nascimento_mes = null,
    telefone_1 = null,
    telefone_1_whatsapp = null,
    telefone_2 = null,
    telefone_2_whatsapp = null,
    email_pessoal = null,
    email_corporativo = null,
    endereco_cep = null,
    endereco_logradouro = null,
    endereco_numero = null,
    endereco_complemento = null,
    endereco_bairro = null,
    endereco_cidade = null,
    endereco_estado = null,
    codigo_verificacao = null,
    slug = null,
    cpf = null,
    recebe_mensagens = false,
    comunicados_optout_em = coalesce(comunicados_optout_em, now()),
    comunicados_optout_origem = coalesce(comunicados_optout_origem, 'secretaria'),
    anonimizada_em = now()
  where id = any (v_ids);
  get diagnostics n_fil = row_count;

  delete from telefones where filiado_id = any (v_ids);
  get diagnostics n_tel = row_count;
  delete from enderecos where filiado_id = any (v_ids);
  get diagnostics n_end = row_count;
  delete from dados_bancarios where filiado_id = any (v_ids);
  get diagnostics n_banc = row_count;
  if to_regclass('public.filiacao_contatos_emergencia') is not null then
    delete from filiacao_contatos_emergencia where filiado_id = any (v_ids);
    get diagnostics n_cont = row_count;
  end if;
  if v_digitos is not null and to_regclass('public.auth_identidades') is not null then
    delete from auth_identidades where emp_proprietaria_id = p_emp and cpf = v_digitos;
    get diagnostics n_ident = row_count;
  end if;
  if to_regclass('public.filiacao_tl_aceites') is not null then
    update filiacao_tl_aceites set cpf = null, ip = null, user_agent = null
     where emp_proprietaria_id = p_emp and (filiacao_id = any (v_ids) or (v_digitos is not null and cpf = v_digitos));
    get diagnostics n_aceites = row_count;
  end if;
  -- Acervo de saúde: fica retido com identidade própria (cifrada pela
  -- aplicação antes desta chamada); o vínculo com o cadastro é cortado.
  if to_regclass('public.saude_assistidos') is not null then
    update saude_assistidos set filiado_id = null where filiado_id = any (v_ids);
    get diagnostics n_saude = row_count;
  end if;

  return jsonb_build_object(
    'ids', to_jsonb(v_ids),
    'filiacoes', n_fil,
    'telefones', n_tel,
    'enderecos', n_end,
    'dados_bancarios', n_banc,
    'contatos_emergencia', n_cont,
    'identidades_acesso', n_ident,
    'aceites', n_aceites,
    'saude_desvinculados', n_saude
  );
end;
$$;


--
-- Name: auth_diagnostico_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_diagnostico_token(p_token_hash text, p_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with alvo as (
    select t.created_at
    from auth.one_time_tokens t
    where t.token_hash in (
      p_token_hash,
      'pkce_' || p_token_hash,
      regexp_replace(p_token_hash, '^pkce_', '')
    )
    order by t.created_at desc
    limit 1
  )
  select jsonb_build_object(
    'token_encontrado', exists (select 1 from alvo),
    'token_criado_em', (select created_at from alvo),
    'ultimo_token_email_em', case
      when p_email is null then null
      else (
        select max(t.created_at)
        from auth.one_time_tokens t
        where lower(t.relates_to) = lower(p_email)
      )
    end
  );
$$;


--
-- Name: cat_bool(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cat_bool(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case lower(public.cat_nz(p))
    when 'sim'   then true
    when 'true'  then true
    when 'não'   then false
    when 'nao'   then false
    when 'false' then false
    else null
  end
$$;


--
-- Name: cat_cid(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cat_cid(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with v as (select upper(public.cat_nz(p)) as x)
  select case
    when x is null then null
    when x ~ '^[A-Z]\d{2}(\.\d)?$' then x
    when x ~ '^[A-Z]\d{2}[\s.\-]+\d$'
      then regexp_replace(x, '^([A-Z]\d{2})[\s.\-]+(\d)$', '\1.\2')
    when x ~ '^[A-Z]\d{3}$'
      then regexp_replace(x, '^([A-Z]\d{2})(\d)$', '\1.\2')
    when x ~ '^[A-Z]\d{2}[\s.\-]+$'
      then regexp_replace(x, '^([A-Z]\d{2})[\s.\-]+$', '\1')
    else x
  end
  from v
$_$;


--
-- Name: cat_codigo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cat_codigo(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select (regexp_match(public.cat_nz(p), '^(\d{9})\s*[–—-]\s*.+$'))[1]
$_$;


--
-- Name: cat_data(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cat_data(p text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v   text := public.cat_nz(p);
  m   text[];
  mes int;
begin
  if v is null then return null; end if;

  m := regexp_match(v, '^([A-Za-zçÇ]+)\.?\s+(\d{1,2}),\s*(\d{4})');
  if m is null then return null; end if;

  mes := case lower(left(m[1], 3))
    when 'jan' then 1
    when 'fev' then 2  when 'feb' then 2
    when 'mar' then 3
    when 'abr' then 4  when 'apr' then 4
    when 'mai' then 5  when 'may' then 5
    when 'jun' then 6
    when 'jul' then 7
    when 'ago' then 8  when 'aug' then 8
    when 'set' then 9  when 'sep' then 9
    when 'out' then 10 when 'oct' then 10
    when 'nov' then 11
    when 'dez' then 12 when 'dec' then 12
    else null
  end;
  if mes is null then return null; end if;

  return make_date(m[3]::int, mes, m[2]::int);
exception when others then
  return null;   -- data impossível (ex.: 31 de fevereiro) não derruba a carga
end $$;


--
-- Name: cat_descricao(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cat_descricao(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select public.cat_sentenca(
    coalesce((regexp_match(public.cat_nz(p), '^\d{9}\s*[–—-]\s*(.+)$'))[1],
             public.cat_nz(p))
  )
$_$;


--
-- Name: cat_nz(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cat_nz(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select nullif(btrim(regexp_replace(coalesce(p, ''), '\s+', ' ', 'g')), '')
$$;


--
-- Name: cat_sentenca(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cat_sentenca(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when public.cat_nz(p) is null then null
    else upper(left(public.cat_nz(p), 1)) || lower(substr(public.cat_nz(p), 2))
  end
$$;


--
-- Name: cat_titulo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cat_titulo(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select nullif(btrim(string_agg(
    case
      when palavra = '' then ''
      when ord > 1 and lower(palavra) in ('da','de','do','das','dos','e')
        then lower(palavra)
      when length(palavra) <= 2 or palavra like '%/%' or palavra like '%.%'
        then upper(palavra)
      else upper(left(palavra, 1)) || lower(substr(palavra, 2))
    end, ' ' order by ord), ''), '')
  from regexp_split_to_table(public.cat_nz(p), '\s+') with ordinality as t(palavra, ord)
$$;


--
-- Name: filiacoes_nascimento_dia_mes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.filiacoes_nascimento_dia_mes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.nascimento_data is null then
    new.nascimento_dia := null;
    new.nascimento_mes := null;
  else
    new.nascimento_dia := extract(day from new.nascimento_data)::int;
    new.nascimento_mes := extract(month from new.nascimento_data)::int;
  end if;
  return new;
end $$;


--
-- Name: filiados_por_matricula_vinculo(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.filiados_por_matricula_vinculo(p_emp uuid, p_termo text, p_limite integer DEFAULT 200) RETURNS TABLE(filiado_id uuid, matricula text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with t as (
    select ltrim(upper(regexp_replace(coalesce(p_termo, ''), '[^A-Za-z0-9]', '', 'g')), '0') as termo
  ),
  achados as (
    -- A matrícula normalizada só tem [0-9A-Z]; "[" vem logo depois de "Z",
    -- então [termo, termo || '[') é exatamente "começa com termo".
    select v.filiado_id, v.matricula
    from public.filiacao_vinculos v, t
    where length(t.termo) >= 3
      and v.emp_proprietaria_id = p_emp
      and ltrim(upper(regexp_replace(v.matricula, '[^A-Za-z0-9]', '', 'g')), '0') ~>=~ t.termo
      and ltrim(upper(regexp_replace(v.matricula, '[^A-Za-z0-9]', '', 'g')), '0') ~<~ (t.termo || '[')
    union all
    select v.filiado_id, v.fonte_pg_matricula
    from public.filiacao_vinculos v, t
    where length(t.termo) >= 3
      and v.emp_proprietaria_id = p_emp
      and ltrim(upper(regexp_replace(v.fonte_pg_matricula, '[^A-Za-z0-9]', '', 'g')), '0') ~>=~ t.termo
      and ltrim(upper(regexp_replace(v.fonte_pg_matricula, '[^A-Za-z0-9]', '', 'g')), '0') ~<~ (t.termo || '[')
  )
  select distinct on (a.filiado_id) a.filiado_id, a.matricula
  from achados a
  where a.filiado_id is not null
  order by a.filiado_id
  limit greatest(1, least(coalesce(p_limite, 200), 1000));
$$;


--
-- Name: hospedagem_gravar_alocacao(uuid, uuid, bigint, uuid, integer, text, date[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hospedagem_gravar_alocacao(p_emp uuid, p_hotel uuid, p_versao bigint, p_cupom uuid, p_quarto integer, p_sexo text, p_noites date[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_versao bigint;
begin
  select alocacao_versao into v_versao
  from hospedagem_hotel
  where id = p_hotel and emp_proprietaria_id = p_emp
  for update;
  if not found then
    return 'hotel_inexistente';
  end if;
  if v_versao <> p_versao then
    return 'conflito';
  end if;

  -- Remanejamento reaproveita a função: a estadia sai do quarto antigo.
  delete from hospedagem_alocacoes where cupom_id = p_cupom;
  insert into hospedagem_alocacoes (emp_proprietaria_id, hotel_id, cupom_id, noite, quarto, sexo)
  select p_emp, p_hotel, p_cupom, n, p_quarto, p_sexo
  from unnest(p_noites) as n;

  update hospedagem_cupom set quarto = p_quarto where id = p_cupom;
  update hospedagem_hotel set alocacao_versao = alocacao_versao + 1 where id = p_hotel;
  return 'ok';
end;
$$;


--
-- Name: mesclar_filiacoes(uuid, uuid, uuid[], jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mesclar_filiacoes(p_emp uuid, p_principal uuid, p_secundarios uuid[], p_campos jsonb, p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  -- Campos do cadastro que a tela deixa escolher entre os duplicados.
  permitidos text[] := array[
    'nome_completo', 'nome_social', 'cpf', 'matricula_sindical', 'sexo', 'nascimento_data',
    'email_pessoal', 'email_corporativo', 'telefone_1', 'telefone_1_whatsapp', 'telefone_2',
    'telefone_2_whatsapp', 'endereco_cep', 'endereco_logradouro', 'endereco_numero',
    'endereco_complemento', 'endereco_bairro', 'endereco_cidade', 'endereco_estado',
    'filiacao_condicao', 'tl_lgpd_id', 'tl_lgpd_data', 'tl_desconto_id', 'tl_desconto_data',
    'foto', 'recebe_mensagens'
  ];
  ref record;
  campo text;
  n integer;
  movidos jsonb := '{}'::jsonb;
  pendentes jsonb := '[]'::jsonb;
  nomes text;
  todos uuid[] := array[p_principal] || p_secundarios;
  par record;
  v_fica filiacao_vinculos;
  v_sai filiacao_vinculos;
  aberto boolean;
  unificados integer := 0;
  sem_unificar uuid[] := '{}';
  -- "vínculo:cadastro": o vínculo já absorveu um do cadastro. Cada vínculo
  -- absorve no máximo UM de cada cadastro, para não fundir dois vínculos que
  -- já conviviam num mesmo cadastro.
  absorvidos text[] := '{}';
begin
  if p_secundarios is null or array_length(p_secundarios, 1) is null then
    raise exception 'Escolha ao menos um cadastro para incorporar.';
  end if;
  if p_principal = any(p_secundarios) then
    raise exception 'O cadastro principal não pode estar entre os incorporados.';
  end if;
  if not exists (
    select 1 from filiacoes
    where id = p_principal and emp_proprietaria_id = p_emp and filiacao_excluida is not true
  ) then
    raise exception 'Cadastro principal não encontrado (ou já excluído).';
  end if;
  if (
    select count(*) from filiacoes
    where id = any(p_secundarios) and emp_proprietaria_id = p_emp and filiacao_excluida is not true
  ) <> array_length(p_secundarios, 1) then
    raise exception 'Algum dos cadastros a incorporar não existe, é de outra entidade ou já foi excluído.';
  end if;

  -- 1. Os incorporados saem primeiro: liberam CPF e matrícula para o principal.
  select string_agg(coalesce(nome_completo, '?') || ' (mat. ' || coalesce(matricula_sindical, '—') || ')', '; ')
    into nomes from filiacoes where id = any(p_secundarios);
  update filiacoes
     set filiacao_excluida = true,
         mesclado_em_id = p_principal,
         mesclado_em = now(),
         mesclado_por = p_usuario,
         updated_at = now()
   where id = any(p_secundarios);

  -- 2. Campos escolhidos gravados no principal.
  for campo in select jsonb_object_keys(coalesce(p_campos, '{}'::jsonb)) loop
    if campo = any(permitidos) then
      execute format(
        'update filiacoes set %I = (jsonb_populate_record(null::filiacoes, $1)).%I where id = $2',
        campo, campo
      ) using p_campos, p_principal;
    end if;
  end loop;
  update filiacoes
     set matricula_sindical_numero = case
           when matricula_sindical ~ '^\d{1,9}$' then matricula_sindical::integer else null end,
         updated_at = now()
   where id = p_principal;

  -- 3. Vínculos repetidos entre os cadastros (antes de movê-los): o mesmo
  --    emprego — mesma fonte, mesma matrícula, períodos que se sobrepõem —
  --    registrado em cadastros DIFERENTES vira um só. Um par por volta; cada
  --    volta apaga um vínculo, então o laço termina.
  loop
    select a.id as fica, b.id as sai into par
      from filiacao_vinculos a
      join filiacao_vinculos b
        on b.fonte_pagadora_id = a.fonte_pagadora_id
       and b.filiado_id <> a.filiado_id
       and nullif(ltrim(btrim(b.matricula), '0'), '') = nullif(ltrim(btrim(a.matricula), '0'), '')
       and coalesce(a.data_filiacao, '-infinity'::date) <= coalesce(b.data_desfiliacao, 'infinity'::date)
       and coalesce(b.data_filiacao, '-infinity'::date) <= coalesce(a.data_desfiliacao, 'infinity'::date)
     where a.filiado_id = any(todos) and b.filiado_id = any(todos)
       and a.emp_proprietaria_id = p_emp and b.emp_proprietaria_id = p_emp
       and not (b.id = any(sem_unificar))
       and not ((a.id::text || ':' || b.filiado_id::text) = any(absorvidos))
       and not ((b.id::text || ':' || a.filiado_id::text) = any(absorvidos))
     order by
       (coalesce(a.ficha_filiacao, a.filiacao_ficha, a.carta_desfiliacao, a.filiacao_desfiliacao_carta) is not null) desc,
       (a.filiado_id = p_principal) desc,
       a.data_filiacao nulls last, a.created_at, a.id, b.id
     limit 1;
    exit when not found;

    select * into v_fica from filiacao_vinculos where id = par.fica;
    select * into v_sai from filiacao_vinculos where id = par.sai;
    -- Se um dos dois segue aberto, o vínculo unificado segue aberto: dados de
    -- saída do outro não passam para ele (ficam na cópia do prontuário).
    aberto := v_fica.data_desfiliacao is null or v_sai.data_desfiliacao is null;
    begin
      for campo in
        select c.column_name::text
          from information_schema.columns c
         where c.table_schema = 'public' and c.table_name = 'filiacao_vinculos'
           and c.is_generated = 'NEVER'
           and c.column_name not in (
             'id', 'filiado_id', 'emp_proprietaria_id', 'created_at', 'bubble_id', 'slug',
             'data_filiacao', 'data_desfiliacao', 'ficha_filiacao_aceita', 'carta_desfiliacao_aceita'
           )
           and not (aberto and c.column_name in (
             'carta_desfiliacao', 'filiacao_desfiliacao_carta', 'filiacao_desfiliacao_comprovante',
             'filiacao_data_saida', 'data_saida_demissao', 'fonte_pg_demissao'
           ))
      loop
        execute format(
          'update filiacao_vinculos set %1$I = (jsonb_populate_record(null::filiacao_vinculos, $1)).%1$I
            where id = $2 and (%1$I is null or %1$I::text = '''') and coalesce($1 ->> %1$L, '''') <> ''''',
          campo
        ) using to_jsonb(v_sai), par.fica;
      end loop;
      update filiacao_vinculos
         set data_filiacao = least(v_fica.data_filiacao, v_sai.data_filiacao),
             data_desfiliacao = case when aberto then null
                                     else greatest(v_fica.data_desfiliacao, v_sai.data_desfiliacao) end,
             ficha_filiacao_aceita = coalesce(v_fica.ficha_filiacao_aceita, false) or coalesce(v_sai.ficha_filiacao_aceita, false),
             carta_desfiliacao_aceita = case when aberto then v_fica.carta_desfiliacao_aceita
               else coalesce(v_fica.carta_desfiliacao_aceita, false) or coalesce(v_sai.carta_desfiliacao_aceita, false) end
       where id = par.fica;

      -- O que aponta para o vínculo removido passa para o que fica.
      for ref in
        select cl.relname::text as tabela, att.attname::text as coluna
          from pg_constraint con
          join pg_class cl on cl.oid = con.conrelid
          join pg_namespace ns on ns.oid = cl.relnamespace
          join pg_attribute att on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
         where con.contype = 'f'
           and con.confrelid = 'public.filiacao_vinculos'::regclass
           and ns.nspname = 'public'
        union
        select c.table_name::text, c.column_name::text
          from information_schema.columns c
         where c.table_schema = 'public' and c.table_name = 'oficios_filiados' and c.column_name = 'vinculo_id'
      loop
        execute format('update %I set %I = $1 where %I = $2', ref.tabela, ref.coluna, ref.coluna)
          using par.fica, par.sai;
      end loop;

      insert into filiacao_prontuario (filiacao_id, data, tipo, descricao, diretor_funcionario_id, emp_proprietaria_id, created_at, modified_at)
      values (
        p_principal, now(), 'Atualização cadastral',
        'Vínculos repetidos unificados na mesclagem (mesma fonte, matrícula ' || btrim(v_fica.matricula) ||
        '): ficou um só, com filiação em ' ||
        coalesce(to_char(least(v_fica.data_filiacao, v_sai.data_filiacao), 'DD/MM/YYYY'), 'data não informada') ||
        '. Cópia do vínculo removido: ' || jsonb_strip_nulls(to_jsonb(v_sai))::text,
        p_usuario, p_emp, now(), now()
      );
      delete from filiacao_vinculos where id = par.sai;
      absorvidos := absorvidos || (v_fica.id::text || ':' || v_sai.filiado_id::text);
      unificados := unificados + 1;
    exception when unique_violation or foreign_key_violation then
      -- Algo impede juntar este par: os dois seguem, e o laço não volta a ele.
      sem_unificar := sem_unificar || par.sai;
    end;
  end loop;

  -- 4. Tudo que aponta para os incorporados passa a apontar para o principal.
  for ref in
    select cl.relname::text as tabela, att.attname::text as coluna
      from pg_constraint con
      join pg_class cl on cl.oid = con.conrelid
      join pg_namespace ns on ns.oid = cl.relnamespace
      join pg_attribute att on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
     where con.contype = 'f'
       and con.confrelid = 'public.filiacoes'::regclass
       and ns.nspname = 'public'
       and cl.relname <> 'filiacoes'
    union
    select c.table_name::text, c.column_name::text
      from information_schema.columns c
     where c.table_schema = 'public'
       and (c.table_name::text, c.column_name::text) in (('diretoria_integrantes', 'filiacao_id'), ('oficios_filiados', 'filiacao_id'))
  loop
    begin
      execute format('update %I set %I = $1 where %I = any($2)', ref.tabela, ref.coluna, ref.coluna)
        using p_principal, p_secundarios;
      get diagnostics n = row_count;
      if n > 0 then
        movidos := movidos || jsonb_build_object(ref.tabela || '.' || ref.coluna, n);
      end if;
    exception when unique_violation then
      -- O principal já tem a mesma linha (ex.: o mesmo ofício): fica no
      -- incorporado, que continua consultável pelo histórico.
      pendentes := pendentes || to_jsonb(ref.tabela || '.' || ref.coluna);
    end;
  end loop;

  -- Quem já tinha sido incorporado por um dos incorporados passa a apontar
  -- para o principal (mesclagens em cadeia).
  update filiacoes set mesclado_em_id = p_principal where mesclado_em_id = any(p_secundarios);

  -- 5. Registro no prontuário do principal.
  insert into filiacao_prontuario (filiacao_id, data, tipo, descricao, diretor_funcionario_id, emp_proprietaria_id, created_at, modified_at)
  values (
    p_principal, now(), 'Atualização cadastral',
    'Cadastro duplicado mesclado: incorporou ' || nomes || '. O histórico foi movido para este cadastro; os incorporados ficaram excluídos.',
    p_usuario, p_emp, now(), now()
  );

  return jsonb_build_object('movidos', movidos, 'pendentes', pendentes, 'vinculos_unificados', unificados);
end;
$_$;


--
-- Name: mesclar_fornecedores(uuid, uuid, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mesclar_fornecedores(p_emp uuid, p_principal uuid, p_secundarios uuid[], p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  ref record;
  campo text;
  n integer;
  movidos jsonb := '{}'::jsonb;
  pendentes jsonb := '[]'::jsonb;
  sec uuid;
  v_sai empresa;
begin
  if p_secundarios is null or array_length(p_secundarios, 1) is null then
    raise exception 'Escolha ao menos um cadastro para incorporar.';
  end if;
  if p_principal = any(p_secundarios) then
    raise exception 'O cadastro principal não pode estar entre os incorporados.';
  end if;
  if not exists (
    select 1 from empresa where id = p_principal and emp_proprietaria_id = p_emp and mesclado_em_id is null
  ) then
    raise exception 'Cadastro principal não encontrado (ou já incorporado a outro).';
  end if;
  if (
    select count(*) from empresa
     where id = any(p_secundarios) and emp_proprietaria_id = p_emp and mesclado_em_id is null
  ) <> array_length(p_secundarios, 1) then
    raise exception 'Algum dos cadastros a incorporar não existe, é de outra entidade ou já foi incorporado.';
  end if;
  -- Uma entidade (tenant) nunca é incorporada.
  if exists (select 1 from empresa where emp_proprietaria_id = any(p_secundarios))
     or exists (select 1 from tenants where empresa_id = any(p_secundarios)) then
    raise exception 'Um dos cadastros é a própria entidade e não pode ser incorporado.';
  end if;

  -- 1. Campos vazios do principal completados pelos incorporados (na ordem).
  foreach sec in array p_secundarios loop
    select * into v_sai from empresa where id = sec;
    for campo in
      select c.column_name::text
        from information_schema.columns c
       where c.table_schema = 'public' and c.table_name = 'empresa'
         and c.is_generated = 'NEVER'
         and c.data_type <> 'boolean'
         and c.column_name not in (
           'id', 'emp_proprietaria_id', 'created_at', 'updated_at', 'bubble_id', 'slug',
           'inativa', 'inativa_data', 'mesclado_em_id', 'mesclado_em', 'mesclado_por'
         )
    loop
      execute format(
        'update empresa set %1$I = (jsonb_populate_record(null::empresa, $1)).%1$I
          where id = $2 and (%1$I is null or %1$I::text = '''') and coalesce($1 ->> %1$L, '''') <> ''''',
        campo
      ) using to_jsonb(v_sai), p_principal;
    end loop;
  end loop;
  -- Papéis somam: se um dos cadastros era empregador, locadora, conveniador
  -- ou entidade apoiada, o principal passa a ser. Bloqueio também soma.
  update empresa p
     set empresa = coalesce(p.empresa, false) or s.empresa,
         locadora_veiculos = coalesce(p.locadora_veiculos, false) or s.locadora_veiculos,
         conveniador = coalesce(p.conveniador, false) or s.conveniador,
         fundo_pensao = coalesce(p.fundo_pensao, false) or s.fundo_pensao,
         beneficiario_ajuda = coalesce(p.beneficiario_ajuda, false) or s.beneficiario_ajuda,
         entidade_apoiada = coalesce(p.entidade_apoiada, false) or s.entidade_apoiada,
         fornecedor_bloqueado = coalesce(p.fornecedor_bloqueado, false) or s.fornecedor_bloqueado,
         updated_at = now()
    from (
      select bool_or(coalesce(empresa, false)) as empresa,
             bool_or(coalesce(locadora_veiculos, false)) as locadora_veiculos,
             bool_or(coalesce(conveniador, false)) as conveniador,
             bool_or(coalesce(fundo_pensao, false)) as fundo_pensao,
             bool_or(coalesce(beneficiario_ajuda, false)) as beneficiario_ajuda,
             bool_or(coalesce(entidade_apoiada, false)) as entidade_apoiada,
             bool_or(coalesce(fornecedor_bloqueado, false) or coalesce(bloqueado, false)) as fornecedor_bloqueado
        from empresa where id = any(p_secundarios)
    ) s
   where p.id = p_principal;

  -- 2. Tudo que aponta para os incorporados passa a apontar para o principal.
  --    Fica de fora a posse do registro (emp_proprietaria_id = o tenant) e a
  --    própria tabela empresa (mesclado_em_id, tratado abaixo).
  for ref in
    select cl.relname::text as tabela, att.attname::text as coluna
      from pg_constraint con
      join pg_class cl on cl.oid = con.conrelid
      join pg_namespace ns on ns.oid = cl.relnamespace
      join pg_attribute att on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
     where con.contype = 'f'
       and con.confrelid = 'public.empresa'::regclass
       and ns.nspname = 'public'
       and att.attname <> 'emp_proprietaria_id'
       and cl.relname not in ('empresa', 'tenants')
  loop
    begin
      execute format('update %I set %I = $1 where %I = any($2)', ref.tabela, ref.coluna, ref.coluna)
        using p_principal, p_secundarios;
      get diagnostics n = row_count;
      if n > 0 then
        movidos := movidos || jsonb_build_object(ref.tabela || '.' || ref.coluna, n);
      end if;
    exception when unique_violation then
      -- O principal já tem a mesma linha (ex.: a mesma categoria): fica no
      -- incorporado, que continua consultável.
      pendentes := pendentes || to_jsonb(ref.tabela || '.' || ref.coluna);
    end;
  end loop;

  -- Lista de fornecedores convidados de um pedido de cotação (texto[]).
  if exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = 'compras_pedido' and column_name = 'lista_fornecedores'
  ) then
    foreach sec in array p_secundarios loop
      execute 'update compras_pedido set lista_fornecedores = array_replace(lista_fornecedores, $1, $2)
                where $1 = any(lista_fornecedores)'
        using sec::text, p_principal::text;
    end loop;
  end if;

  -- 3. Incorporados ficam inativos, apontando para o principal; mesclas em
  --    cadeia passam a apontar para o principal também.
  update empresa set mesclado_em_id = p_principal where mesclado_em_id = any(p_secundarios);
  update empresa
     set inativa = true,
         inativa_data = coalesce(inativa_data, (now() at time zone 'America/Sao_Paulo')::date),
         mesclado_em_id = p_principal,
         mesclado_em = now(),
         mesclado_por = p_usuario,
         updated_at = now()
   where id = any(p_secundarios);

  return jsonb_build_object('movidos', movidos, 'pendentes', pendentes);
end;
$_$;


--
-- Name: registrar_auditoria(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_auditoria() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_antes   jsonb;
  v_depois  jsonb;
  v_campos  text[];
  v_emp     uuid;
  v_id      text;
  v_usuario uuid;
  v_papel   text;
  v_hdr     jsonb;
  v_claims  jsonb;
  k         text;
  ignorar   constant text[] := array['updated_at', 'modified_at', 'atualizado_em', 'created_at', 'criado_em'];
  ocultar   constant text[] := array['senha', 'nome_retido_cifrado', 'cpf_retido_cifrado', 'relatorio_cifrado', 'codigo_hash', 'comprovante_hash'];
begin
  if tg_op = 'DELETE' then
    v_antes := to_jsonb(old);
  else
    v_depois := to_jsonb(new);
  end if;

  if tg_op = 'UPDATE' then
    v_antes := to_jsonb(old);
    select coalesce(array_agg(d.key), '{}')
      into v_campos
      from jsonb_each(v_depois) d
     where d.value is distinct from (v_antes -> d.key)
       and not (d.key = any (ignorar));
    if coalesce(array_length(v_campos, 1), 0) = 0 then
      return null;  -- só carimbo mudou: não é alteração de negócio
    end if;
    -- Guarda só os campos que mudaram.
    v_antes  := (select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) from jsonb_each(v_antes)  e where e.key = any (v_campos));
    v_depois := (select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) from jsonb_each(v_depois) e where e.key = any (v_campos));
  end if;

  foreach k in array ocultar loop
    if v_antes  ? k then v_antes  := jsonb_set(v_antes,  array[k], '"[oculto]"'::jsonb); end if;
    if v_depois ? k then v_depois := jsonb_set(v_depois, array[k], '"[oculto]"'::jsonb); end if;
  end loop;

  v_id  := coalesce(to_jsonb(new) ->> 'id', to_jsonb(old) ->> 'id');
  begin
    v_emp := nullif(coalesce(to_jsonb(new) ->> 'emp_proprietaria_id', to_jsonb(old) ->> 'emp_proprietaria_id'), '')::uuid;
  exception when others then
    v_emp := null;
  end;
  if v_emp is null and tg_table_name = 'empresa' then
    begin v_emp := v_id::uuid; exception when others then v_emp := null; end;
  end if;

  begin
    v_hdr := nullif(current_setting('request.headers', true), '')::jsonb;
    v_usuario := nullif(v_hdr ->> 'x-confluir-usuario', '')::uuid;
  exception when others then
    v_usuario := null;
  end;
  begin
    v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
    v_papel := v_claims ->> 'role';
  exception when others then
    v_papel := null;
  end;

  insert into public.auditoria (emp_proprietaria_id, tabela, registro_id, operacao, campos, antes, depois, usuario_id, papel)
  values (v_emp, tg_table_name, v_id, tg_op, v_campos, v_antes, v_depois, v_usuario, v_papel);
  return null;
exception when others then
  raise warning 'auditoria: falha em % (%): %', tg_table_name, tg_op, sqlerrm;
  return null;
end;
$$;


--
-- Name: set_emp_from_jwt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_emp_from_jwt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.emp_proprietaria_id := coalesce(
    new.emp_proprietaria_id,
    nullif(auth.jwt() ->> 'tenant_id', '')::uuid
  );
  return new;
end;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: unificar_condutores(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unificar_condutores(p_emp uuid, p_principal uuid, p_secundario uuid, p_autor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cp veiculos_condutores%rowtype;
  cs veiculos_condutores%rowtype;
  v_movidos jsonb := '{}'::jsonb;
  v_ids uuid[];
  v_sec_mais_nova boolean;
  v_log uuid;
begin
  if p_principal = p_secundario then
    raise exception 'Escolha dois usuários diferentes.';
  end if;
  if (select count(*) from usuarios where id in (p_principal, p_secundario) and emp_proprietaria_id = p_emp) <> 2 then
    raise exception 'Usuários não encontrados neste tenant.';
  end if;

  select * into cp from veiculos_condutores where usuario_id = p_principal and emp_proprietaria_id = p_emp;
  select * into cs from veiculos_condutores where usuario_id = p_secundario and emp_proprietaria_id = p_emp;

  -- 1. Cadastro de condutor + histórico de CNH
  if cs.id is not null and cp.id is null then
    -- Só o secundário tinha cadastro: ele passa a ser do principal.
    update veiculos_condutores set usuario_id = p_principal, updated_at = now() where id = cs.id;
  elsif cs.id is not null then
    v_sec_mais_nova := coalesce(cs.cnh_validade, '-infinity'::date) > coalesce(cp.cnh_validade, '-infinity'::date);
    if v_sec_mais_nova then
      -- A CNH atual passa a ser a do secundário; a do principal vai para o histórico.
      if cp.cnh_numero is not null or cp.cnh_validade is not null then
        insert into veiculos_condutores_cnh (emp_proprietaria_id, condutor_id, cnh_numero, cnh_categoria, cnh_validade, cnh_arquivo_url, origem, usuario_origem_id, registrado_por_id)
        values (p_emp, cp.id, cp.cnh_numero, cp.cnh_categoria, cp.cnh_validade, cp.cnh_arquivo_url, 'unificacao', p_principal, p_autor);
      end if;
      update veiculos_condutores set
        cnh_numero = cs.cnh_numero,
        cnh_categoria = cs.cnh_categoria,
        cnh_validade = cs.cnh_validade,
        cnh_arquivo_url = coalesce(cs.cnh_arquivo_url, cp.cnh_arquivo_url)
      where id = cp.id;
    elsif cs.cnh_numero is not null or cs.cnh_validade is not null then
      insert into veiculos_condutores_cnh (emp_proprietaria_id, condutor_id, cnh_numero, cnh_categoria, cnh_validade, cnh_arquivo_url, origem, usuario_origem_id, registrado_por_id)
      values (p_emp, cp.id, cs.cnh_numero, cs.cnh_categoria, cs.cnh_validade, cs.cnh_arquivo_url, 'unificacao', p_secundario, p_autor);
    end if;
    -- Histórico que já existia no secundário acompanha o cadastro que fica.
    update veiculos_condutores_cnh set condutor_id = cp.id where condutor_id = cs.id;
    -- Autorização: vale a de quem estava autorizado.
    update veiculos_condutores set
      autorizado = cp.autorizado or cs.autorizado,
      autorizado_por_id = case when cp.autorizado then cp.autorizado_por_id else cs.autorizado_por_id end,
      autorizado_em = case when cp.autorizado then cp.autorizado_em else cs.autorizado_em end,
      observacao = nullif(concat_ws(E'\n', cp.observacao, cs.observacao), ''),
      updated_at = now()
    where id = cp.id;
    delete from veiculos_condutores where id = cs.id;
  end if;

  -- 2. Lançamentos do secundário passam para o principal
  with m as (update veiculos_disponibilidade set condutor_id = p_principal
             where condutor_id = p_secundario and emp_proprietaria_id = p_emp returning id)
  select array_agg(id) into v_ids from m;
  v_movidos := v_movidos || jsonb_build_object('veiculos_disponibilidade', coalesce(to_jsonb(v_ids), '[]'::jsonb));

  -- Reserva feita pela própria pessoa: o "solicitado por" acompanha.
  with m as (update veiculos_agendamentos set
               condutor_id = p_principal,
               solicitado_por_id = case when solicitado_por_id = p_secundario then p_principal else solicitado_por_id end
             where condutor_id = p_secundario and emp_proprietaria_id = p_emp returning id)
  select array_agg(id) into v_ids from m;
  v_movidos := v_movidos || jsonb_build_object('veiculos_agendamentos', coalesce(to_jsonb(v_ids), '[]'::jsonb));

  with m as (update veiculos_abastecimentos set usuario_id = p_principal
             where usuario_id = p_secundario and emp_proprietaria_id = p_emp returning id)
  select array_agg(id) into v_ids from m;
  v_movidos := v_movidos || jsonb_build_object('veiculos_abastecimentos', coalesce(to_jsonb(v_ids), '[]'::jsonb));

  -- Infrações não têm coluna de tenant: o usuário já foi conferido acima.
  with m as (update veiculos_infracoes set condutor_infrator_id = p_principal
             where condutor_infrator_id = p_secundario returning id)
  select array_agg(id) into v_ids from m;
  v_movidos := v_movidos || jsonb_build_object('veiculos_infracoes', coalesce(to_jsonb(v_ids), '[]'::jsonb));

  with m as (update veiculos_checklists set inspetor_id = p_principal
             where inspetor_id = p_secundario and emp_proprietaria_id = p_emp returning id)
  select array_agg(id) into v_ids from m;
  v_movidos := v_movidos || jsonb_build_object('veiculos_checklists', coalesce(to_jsonb(v_ids), '[]'::jsonb));

  -- Flag legada (o Bubble lê) acompanha a autorização final.
  update usuarios set cnh_autorizado = coalesce((select autorizado from veiculos_condutores where usuario_id = p_principal), cnh_autorizado)
  where id = p_principal;

  insert into veiculos_condutores_unificacoes (emp_proprietaria_id, principal_usuario_id, secundario_usuario_id, cadastro_removido, cadastro_principal_antes, movidos, feito_por_id)
  values (p_emp, p_principal, p_secundario,
          case when cs.id is null then null else to_jsonb(cs) end,
          case when cp.id is null then null else to_jsonb(cp) end,
          v_movidos, p_autor)
  returning id into v_log;

  return jsonb_build_object('log_id', v_log, 'movidos', (
    select jsonb_object_agg(k, jsonb_array_length(v)) from jsonb_each(v_movidos) as e(k, v)
  ));
end $$;


--
-- Name: unificar_usuarios(uuid, uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unificar_usuarios(p_emp uuid, p_principal uuid, p_secundario uuid, p_autor uuid, p_simular boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  up usuarios%rowtype;
  us usuarios%rowtype;
  ref record;
  v_ids jsonb;
  v_movidos jsonb := '{}'::jsonb;
  v_pendentes jsonb := '[]'::jsonb;
  v_contatos jsonb := '[]'::jsonb;
  v_removidos jsonb;
  v_campos text[] := array[
    'cpf', 'cpf_arquivo', 'foto', 'data_nascimento', 'nascimento_dia', 'nascimento_mes',
    'nascimento_data', 'sexo', 'estado_civil', 'escolaridade', 'whatsapp', 'email_empresa',
    'empresa_matricula', 'vinculo_instituicao', 'vinculo_instituicao_os', 'sindicato_id'
  ];
  v_completados text[] := '{}';
  campo text;
  v_relatorio jsonb;
begin
  if p_principal = p_secundario then
    raise exception 'Escolha duas contas diferentes.';
  end if;
  select * into up from usuarios where id = p_principal and emp_proprietaria_id = p_emp;
  select * into us from usuarios where id = p_secundario and emp_proprietaria_id = p_emp;
  if up.id is null or us.id is null then
    raise exception 'Contas não encontradas neste tenant.';
  end if;
  if us.unificado_em_id is not null then
    raise exception 'A conta % já foi unificada em outra.', coalesce(us.email, us.id::text);
  end if;
  if up.auth_user_id is not null and us.auth_user_id is not null then
    raise exception 'As duas contas têm login. Decida antes qual login fica.';
  end if;
  if us.auth_user_id is not null then
    raise exception 'A conta que sai tem login e a que fica não. Escolha como principal a conta com login.';
  end if;

  begin
    -- 1. Referências
    for ref in
      select cl.relname::text as tabela, att.attname::text as coluna
        from pg_constraint con
        join pg_class cl on cl.oid = con.conrelid
        join pg_namespace ns on ns.oid = cl.relnamespace
        join pg_attribute att on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
       where con.contype = 'f'
         and con.confrelid = 'public.usuarios'::regclass
         and array_length(con.conkey, 1) = 1
         and ns.nspname = 'public'
         -- Registros que documentam unificações apontam de propósito para o secundário.
         and not (cl.relname in ('usuarios_unificacoes', 'veiculos_condutores_unificacoes'))
         and not (cl.relname = 'veiculos_condutores_cnh' and att.attname = 'usuario_origem_id')
         and not (cl.relname = 'usuarios' and att.attname = 'unificado_em_id')
      union
      -- Colunas sem chave declarada que guardam usuário.
      select c.table_name::text, c.column_name::text
        from information_schema.columns c
       where c.table_schema = 'public'
         and (c.table_name, c.column_name) in (
           ('hospedagem_quartos_noite', 'anotado_por'),
           ('hospedagem_cupom', 'presenca_por'),
           ('hospedagem_cupom', 'nao_comparecimento_abonado_por')
         )
    loop
      begin
        execute format(
          'with m as (update %I set %I = $1 where %I = $2 returning 1) select to_jsonb(count(*)) from m',
          ref.tabela, ref.coluna, ref.coluna
        ) using p_principal, p_secundario into v_ids;
        if (v_ids)::int > 0 then
          v_movidos := v_movidos || jsonb_build_object(ref.tabela || '.' || ref.coluna, v_ids);
        end if;
      exception when unique_violation or foreign_key_violation or check_violation then
        v_pendentes := v_pendentes || jsonb_build_object('tabela', ref.tabela, 'coluna', ref.coluna, 'erro', sqlerrm);
      end;
    end loop;

    -- 2. Contatos idênticos que ficaram repetidos no principal
    begin
      with dup as (
        select id, row_number() over (
                 partition by lower(btrim(email)) order by favorito desc nulls last, created_at, id) as n
          from emails where usuario_id = p_principal and email is not null
      ), del as (delete from emails where id in (select id from dup where n > 1) returning to_jsonb(emails.*) as r)
      select coalesce(jsonb_agg(r), '[]'::jsonb) into v_removidos from del;
      v_contatos := v_contatos || v_removidos;
    exception when foreign_key_violation then null;
    end;
    begin
      with dup as (
        select id, row_number() over (
                 partition by regexp_replace(numero, '\D', '', 'g') order by favorito desc nulls last, created_at, id) as n
          from telefones where usuario_id = p_principal and numero is not null
      ), del as (delete from telefones where id in (select id from dup where n > 1) returning to_jsonb(telefones.*) as r)
      select coalesce(jsonb_agg(r), '[]'::jsonb) into v_removidos from del;
      v_contatos := v_contatos || v_removidos;
    exception when foreign_key_violation then null;
    end;
    begin
      with dup as (
        select id, row_number() over (
                 partition by regexp_replace(coalesce(cep, ''), '\D', '', 'g'), lower(btrim(coalesce(numero, ''))),
                              lower(btrim(coalesce(logradouro, '')))
                 order by favorito desc nulls last, (complemento is null), created_at, id) as n
          from enderecos where usuario_id = p_principal
      ), del as (delete from enderecos where id in (select id from dup where n > 1) returning to_jsonb(enderecos.*) as r)
      select coalesce(jsonb_agg(r), '[]'::jsonb) into v_removidos from del;
      v_contatos := v_contatos || v_removidos;
    exception when foreign_key_violation then null;
    end;

    -- 3. Campos vazios do principal completados pelo secundário
    foreach campo in array v_campos loop
      if (to_jsonb(up) -> campo) is not null and (to_jsonb(up) ->> campo) is null
         and (to_jsonb(us) ->> campo) is not null then
        execute format(
          'update usuarios set %I = (select %I from usuarios where id = $2) where id = $1', campo, campo
        ) using p_principal, p_secundario;
        v_completados := v_completados || campo;
      end if;
    end loop;
    update usuarios set
      cnh_autorizado = coalesce(up.cnh_autorizado, false) or coalesce(us.cnh_autorizado, false),
      filiado = coalesce(up.filiado, false) or coalesce(us.filiado, false),
      updated_at = now()
    where id = p_principal;

    -- 4. O secundário sai (sem apagar)
    update usuarios set
      inativo = true,
      deletado = true,
      unificado_em_id = p_principal,
      unificado_em = now(),
      updated_at = now()
    where id = p_secundario;

    insert into usuarios_unificacoes (emp_proprietaria_id, principal_usuario_id, secundario_usuario_id,
      principal_antes, secundario_antes, movidos, pendentes, contatos_removidos, feito_por_id)
    values (p_emp, p_principal, p_secundario, to_jsonb(up), to_jsonb(us), v_movidos, v_pendentes, v_contatos, p_autor);

    v_relatorio := jsonb_build_object(
      'simulado', p_simular,
      'movidos', v_movidos,
      'pendentes', v_pendentes,
      'contatos_removidos', jsonb_array_length(v_contatos),
      'campos_completados', to_jsonb(v_completados)
    );
    if p_simular then
      raise exception 'SIMULACAO_CONFLUIR';
    end if;
  exception when others then
    if sqlerrm = 'SIMULACAO_CONFLUIR' then
      return v_relatorio;   -- tudo acima foi desfeito
    end if;
    raise;
  end;
  return v_relatorio;
end $_$;


--
-- Name: voto_raw_array(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.voto_raw_array(v jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when v is null then '[]'::jsonb
    when jsonb_typeof(v) = 'array' then v
    when jsonb_typeof(v) = 'string' and (v #>> '{}') ~ '^\s*\[' then (v #>> '{}')::jsonb
    else '[]'::jsonb
  end
$$;


--
-- Name: acordo_clausulas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.acordo_clausulas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    acordo_id uuid,
    numero text,
    titulo text,
    texto text,
    categoria text DEFAULT 'outro'::text NOT NULL,
    ordem integer DEFAULT 0 NOT NULL,
    emp_proprietaria_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    tema text,
    grupo text,
    resumo text,
    numero_ordem integer,
    origem text DEFAULT 'manual'::text NOT NULL,
    CONSTRAINT acordo_clausulas_categoria_check CHECK ((categoria = ANY (ARRAY['reajuste'::text, 'beneficio'::text, 'jornada'::text, 'saude'::text, 'seguranca'::text, 'outro'::text])))
);


--
-- Name: COLUMN acordo_clausulas.tema; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.acordo_clausulas.tema IS 'Tema (lista em src/lib/acordos-constantes.ts: TEMAS_CLAUSULA). Sugerido pela IA na extração; a entidade corrige.';


--
-- Name: acordo_coletivo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.acordo_coletivo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tipo text DEFAULT 'act'::text NOT NULL,
    titulo text,
    numero_registro text,
    data_base text,
    vigencia_inicio date,
    vigencia_fim date,
    abrangencia text,
    situacao text DEFAULT 'em_negociacao'::text NOT NULL,
    documento_url text,
    observacoes text,
    emp_proprietaria_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    com_funcionarios_entidade boolean DEFAULT false NOT NULL,
    texto_integral text,
    preambulo text,
    anexos text,
    extracao_em timestamp with time zone,
    extracao_avisos text,
    clausulas_revisadas_em timestamp with time zone,
    clausulas_revisadas_por_id uuid,
    negociacao_id uuid,
    papel_negociacao text,
    rodada_negociacao integer,
    data_documento date,
    CONSTRAINT acordo_coletivo_situacao_check CHECK ((situacao = ANY (ARRAY['em_negociacao'::text, 'vigente'::text, 'arquivado'::text]))),
    CONSTRAINT acordo_coletivo_tipo_check CHECK ((tipo = ANY (ARRAY['act'::text, 'cct'::text])))
);


--
-- Name: COLUMN acordo_coletivo.texto_integral; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.acordo_coletivo.texto_integral IS 'Texto extraído do PDF (base da separação em cláusulas e da busca).';


--
-- Name: COLUMN acordo_coletivo.negociacao_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.acordo_coletivo.negociacao_id IS 'Documento sigiloso de uma negociação (pauta/proposta). Some de Acordos coletivos; ao concluir, o final perde o vínculo e vira vigente.';


