    nome_declarado text,
    cpf_conferido_em timestamp with time zone,
    CONSTRAINT oficios_assinaturas_canal_check CHECK ((canal = ANY (ARRAY['email'::text, 'telegram'::text]))),
    CONSTRAINT oficios_assinaturas_situacao_check CHECK ((situacao = ANY (ARRAY['pendente'::text, 'assinado'::text, 'recusado'::text, 'cancelado'::text])))
);


--
-- Name: TABLE documento_assinaturas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.documento_assinaturas IS 'Envelope de assinatura eletrônica de um documento (ofício, termo de cessão), por assinante: token do link, código por e-mail, hash do conteúdo e certificado. Nome antigo: oficios_assinaturas.';


--
-- Name: COLUMN documento_assinaturas.canal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documento_assinaturas.canal IS 'Por onde o convite e o código de uso único foram entregues: email ou telegram.';


--
-- Name: COLUMN documento_assinaturas.documento_tipo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documento_assinaturas.documento_tipo IS 'oficio | cessao — define de onde sai o conteúdo assinado e o que acontece ao assinar.';


--
-- Name: COLUMN documento_assinaturas.ordem; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documento_assinaturas.ordem IS 'Ordem de assinatura. A cessão tem dois assinantes: cedente (1) e concessionário (2).';


--
-- Name: COLUMN documento_assinaturas.cpf; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documento_assinaturas.cpf IS 'CPF do assinante (só dígitos), informado no envio. Na assinatura da minuta a pessoa digita o CPF e ele precisa bater.';


