    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: lgpd_retencoes_vencidas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.lgpd_retencoes_vencidas WITH (security_invoker='on') AS
 SELECT id AS assistido_id,
    retencao_ate,
    retencao_regime,
    retencao_observacao,
    exposicao_cancerigeno_quimico,
    exposicao_radiacao_ionizante,
    (CURRENT_DATE - retencao_ate) AS dias_vencidos,
    ( SELECT count(*) AS count
           FROM public.saude_atendimentos t
          WHERE (t.assistido_id = a.id)) AS atendimentos
   FROM public.saude_assistidos a
  WHERE ((retencao_ate IS NOT NULL) AND (retencao_ate < CURRENT_DATE) AND (retencao_regime IS NULL))
  ORDER BY retencao_ate;


--
-- Name: VIEW lgpd_retencoes_vencidas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.lgpd_retencoes_vencidas IS 'Candidatos a descarte, para ANÁLISE humana. Registros com retencao_regime preenchido ficam de fora: seguem norma própria, mais longa que a NR-07.';


