-- Name: usuarios_ocupacoes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.usuarios_ocupacoes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    emp_proprietaria_id uuid,
    conta_id uuid NOT NULL,
    pessoa_id uuid NOT NULL,
    inicio date NOT NULL,
    fim date,
    motivo text NOT NULL,
    observacao text,
    registrado_por_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT usuarios_ocupacoes_motivo_check CHECK ((motivo = ANY (ARRAY['titular'::text, 'ferias'::text, 'afastamento'::text, 'substituicao'::text]))),
    CONSTRAINT usuarios_ocupacoes_periodo_check CHECK (((fim IS NULL) OR (fim >= inicio))),
    CONSTRAINT usuarios_ocupacoes_pessoa_check CHECK ((pessoa_id <> conta_id))
);


