--
-- Name: veiculos_ultima_movimentacao; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.veiculos_ultima_movimentacao WITH (security_invoker='true') AS
 SELECT DISTINCT ON (veiculo_id) id,
    veiculo_id,
    emp_proprietaria_id,
    condutor_id,
    destino,
    motivo,
    data_retirada,
    retirada_em,
    sede_retirada,
    sede_retirada_os,
    hodometro_retirada,
    data_devolucao,
    devolucao_em,
    sede_devolucao,
    sede_devolucao_os,
    hodometro_devolucao,
    previsao_retorno,
    registrado_por_id,
    created_at
   FROM public.veiculos_disponibilidade
  WHERE (veiculo_id IS NOT NULL)
  ORDER BY veiculo_id, data_retirada DESC NULLS LAST, retirada_em DESC NULLS LAST, created_at DESC;


