    valor_total numeric NOT NULL,
    arquivo text NOT NULL,
    observacao text,
    processo_compra_id uuid,
    ordem_pagamento_id uuid,
    criado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
