    CONSTRAINT viagens_faturas_valor_itens_check CHECK ((valor_itens >= (0)::numeric)),
    CONSTRAINT viagens_faturas_valor_taxas_check CHECK ((valor_taxas >= (0)::numeric)),
    CONSTRAINT viagens_faturas_valor_total_check CHECK ((valor_total > (0)::numeric))
);


