--
-- Name: viagens_itens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.viagens_itens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    emp_proprietaria_id uuid,
    solicitacao_id uuid NOT NULL,
    tipo text NOT NULL,
    ordem integer DEFAULT 0 NOT NULL,
    modal text,
    origem text,
    destino text,
    data_viagem date,
    saida_criterio text,
    saida_hora time without time zone,
    chegada_criterio text,
    chegada_hora time without time zone,
    bagagem_extra boolean DEFAULT false NOT NULL,
    bagagem_descricao text,
    cidade text,
    checkin date,
    checkout date,
    necessidades_especiais text,
    observacoes text,
    fornecedor_id uuid,
    localizador text,
    reserva_descricao text,
    valor numeric,
    voucher text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    fatura_id uuid,
    centro_custo_id uuid,
    CONSTRAINT viagens_itens_chegada_criterio_check CHECK ((chegada_criterio = ANY (ARRAY['ate'::text, 'depois'::text]))),
    CONSTRAINT viagens_itens_hospedagem_check CHECK (((tipo <> 'hospedagem'::text) OR ((cidade IS NOT NULL) AND (checkin IS NOT NULL) AND (checkout IS NOT NULL) AND (checkout > checkin)))),
    CONSTRAINT viagens_itens_modal_check CHECK ((modal = ANY (ARRAY['aerea'::text, 'rodoviaria'::text]))),
    CONSTRAINT viagens_itens_passagem_check CHECK (((tipo <> 'passagem'::text) OR ((modal IS NOT NULL) AND (origem IS NOT NULL) AND (destino IS NOT NULL) AND (data_viagem IS NOT NULL)))),
    CONSTRAINT viagens_itens_saida_criterio_check CHECK ((saida_criterio = ANY (ARRAY['ate'::text, 'depois'::text]))),
    CONSTRAINT viagens_itens_tipo_check CHECK ((tipo = ANY (ARRAY['passagem'::text, 'hospedagem'::text]))),
    CONSTRAINT viagens_itens_valor_check CHECK (((valor IS NULL) OR (valor >= (0)::numeric)))
);


--
-- Name: TABLE viagens_itens; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.viagens_itens IS 'Cada trecho de passagem (aérea ou rodoviária) ou estadia de hospedagem de uma viagem.';


--
-- Name: COLUMN viagens_itens.saida_criterio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.viagens_itens.saida_criterio IS 'ate = sair no máximo até saida_hora; depois = sair a partir de saida_hora.';


--
