COMMENT ON COLUMN public.viagens_itens.centro_custo_id IS 'Conta em que o item foi faturado (a sugerida pelo de-para ou a escolhida na fatura).';


--
-- Name: viagens_solicitacoes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.viagens_solicitacoes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    emp_proprietaria_id uuid,
    numero bigint NOT NULL,
    beneficiario_tipo text NOT NULL,
    beneficiario_usuario_id uuid,
    convidado_nome text,
    convidado_cpf text,
    convidado_nascimento date,
    convidado_email text,
    convidado_telefone text,
    solicitante_id uuid,
    departamento_id uuid,
    evento_id uuid,
    evento_inscricao_id uuid,
    motivo text NOT NULL,
    situacao text DEFAULT 'solicitada'::text NOT NULL,
    motivo_situacao text,
    atendido_por uuid,
    atendido_em timestamp with time zone,
    encerrado_em timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    evento_externo text,
    CONSTRAINT viagens_solicitacoes_beneficiario_check CHECK ((((beneficiario_tipo = 'convidado'::text) AND (convidado_nome IS NOT NULL)) OR ((beneficiario_tipo <> 'convidado'::text) AND (beneficiario_usuario_id IS NOT NULL)))),
    CONSTRAINT viagens_solicitacoes_beneficiario_tipo_check CHECK ((beneficiario_tipo = ANY (ARRAY['funcionario'::text, 'diretor'::text, 'convidado'::text]))),
    CONSTRAINT viagens_solicitacoes_situacao_check CHECK ((situacao = ANY (ARRAY['solicitada'::text, 'em_atendimento'::text, 'atendida'::text, 'cancelada'::text, 'recusada'::text])))
);


--
-- Name: TABLE viagens_solicitacoes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.viagens_solicitacoes IS 'Pedido de viagem (passagens e/ou hospedagens) para diretor, funcionário ou convidado. Os trechos e estadias ficam em viagens_itens.';


--
