--

COMMENT ON COLUMN public.viagens_solicitacoes.evento_externo IS 'Nome do evento de fora (não cadastrado em Eventos). Excludente com evento_id.';


--
-- Name: viagens_solicitacoes_numero_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.viagens_solicitacoes ALTER COLUMN numero ADD GENERATED BY DEFAULT AS IDENTITY (
