--

CREATE POLICY tenant_isolation_pai ON public.aso TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.usuarios p
  WHERE ((p.id = aso.funcionario_id) AND (p.emp_proprietaria_id = ((auth.jwt() ->> 'tenant_id'::text))::uuid))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.usuarios p
  WHERE ((p.id = aso.funcionario_id) AND (p.emp_proprietaria_id = ((auth.jwt() ->> 'tenant_id'::text))::uuid)))));


