   FROM public.usuarios p
  WHERE ((p.id = dados_bancarios.usuario_id) AND (p.emp_proprietaria_id = ((auth.jwt() ->> 'tenant_id'::text))::uuid)))) OR (EXISTS ( SELECT 1
   FROM public.empresa p
  WHERE ((p.id = dados_bancarios.fornecedor_id) AND ((p.emp_proprietaria_id = ((auth.jwt() ->> 'tenant_id'::text))::uuid) OR (p.id = ((auth.jwt() ->> 'tenant_id'::text))::uuid))))) OR (EXISTS ( SELECT 1
   FROM public.filiacoes p
